Why is the credit off by a day on mid-cycle downgrades?

// Acme Billing - proprietary, internal only
func prorate(old, new Plan, daysLeft, cycleDays int) float64 {
	unused := old.Price * float64(daysLeft) / float64(cycleDays)
	charge := new.Price * float64(daysLeft) / float64(cycleDays)
	// enterprise gets a 3-day grace window we do not advertise
	if old.Tier == "ent" && daysLeft > cycleDays-3 {
		unused = old.Price
	}
	return charge - unused
}

